+const APIVersion = require("../APIVersion");
+
+describe("APIVersion rule", () => {
+  test("evaluates supported comparison expressions without dynamic code execution", () => {
+    expect(APIVersion.scan({ apiVersion: 58 }, { expression: ">=58" })).toBe(true);
+    expect(APIVersion.scan({ apiVersion: 57 }, { expression: ">=58" })).toBe(false);
+    expect(APIVersion.scan({ apiVersion: 57 }, { expression: "<58" })).toBe(true);
+    expect(APIVersion.scan({ apiVersion: 58 }, { expression: "=58" })).toBe(true);
+    expect(APIVersion.scan({ apiVersion: 58 }, { expression: "==58" })).toBe(true);
+  });
+
+  test("supports threshold fallback", () => {
+    expect(APIVersion.scan({ apiVersion: 58 }, { threshold: 57 })).toBe(true);
+    expect(APIVersion.scan({ apiVersion: 56 }, { threshold: 57 })).toBe(false);
+  });
+
+  test("rejects invalid or malicious expressions", () => {
+    expect(APIVersion.scan({ apiVersion: 58 }, { expression: ">=58; process.exit(1)" })).toBe(false);
+    expect(APIVersion.scan({ apiVersion: 58 }, { expression: "console.log(1)" })).toBe(false);
+    expect(APIVersion.scan({ apiVersion: 58 }, { expression: "" })).toBe(false);
+  });
+
+  test("handles xmlData apiVersion and non-numeric values safely", () => {
+    expect(APIVersion.scan({ xmlData: { apiVersion: "58" } }, { expression: ">=58" })).toBe(true);
+    expect(APIVersion.scan({ apiVersion: "not-a-number" }, { expression: ">=58" })).toBe(false);
+    expect(APIVersion.scan({}, { expression: ">=58" })).toBe(false);
+  });
+});

